contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5_000);

        bool initBefore = c.initialized();

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        bool secondReverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            !initBefore &&
            c.initialized() &&
            secondReverted &&
            c.baseToken() == _baseToken &&
            c.nft() == _nft &&
            c.virtualBaseTokenReserves() == _virtualBaseTokenReserves &&
            c.virtualNftReserves() == _virtualNftReserves &&
            c.changeFee() == _changeFee &&
            c.feeRate() == _feeRate &&
            c.merkleRoot() == _merkleRoot &&
            c.useStolenNftOracle() == _useStolenNftOracle &&
            c.payRoyalties() == _payRoyalties
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofArr, bool[] calldata flagsArr) public {
        require(c.merkleRoot() == bytes32(0));

        uint256 expected = uint256(tokenIds.length) * 1e18;

        bytes32[] memory proofMem = proofArr;
        bool[] memory flagsMem = flagsArr;
        C.MerkleMultiProof memory mp = C.MerkleMultiProof({proof: proofMem, flags: flagsMem});

        uint256 result = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mp);

        assert(result == expected);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 inputAmount) public {
        // Fresh pool: uninitialized, so baseToken() == address(0) and changeFee() == 0.
        require(c.baseToken() == address(0));
        require(c.initialized() == false);
        require(inputAmount <= 1e24);

        uint256 changeFee = c.changeFee();
        // With baseToken == address(0) the exponent is 18 - 4 = 14,
        // so feeAmount == inputAmount * changeFee * 10**14 / 1e18 == inputAmount * changeFee / 1e4.
        uint256 expectedFee = inputAmount * changeFee / 10000;

        (uint256 feeAmount, uint256 protocolFeeAmount) = c.changeFeeQuote(inputAmount);

        assert(feeAmount == expectedFee && protocolFeeAmount == feeAmount * 0 / 10000 && feeAmount == 0);
    }

    receive() external payable {}
}

