contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public {
        // The deciding call on a fresh pool: virtualNftReserves is 0, so
        // price() must revert (division by zero) rather than return.
        bool reverted;
        try c.price() { reverted = false; } catch { reverted = true; }
