contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        bool reverted1;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        bool initializedAfter = c.initialized();

        // A second initialize() must always revert (AlreadyInitialized),
        // whether or not the first one succeeded.
        bool reverted2;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        assert(
            reverted1 == (_feeRate > 5_000) &&
            initializedAfter == !reverted1 &&
            reverted2
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256[] memory tokenIds, uint256[] memory tokenWeights) public {
        require(tokenIds.length == tokenWeights.length);

        // Fresh pool: merkleRoot is still bytes32(0), so the whitelist proof
        // must be bypassed and the default weight of 1e18 per token used.
        require(c.merkleRoot() == bytes32(0));

        C.MerkleMultiProof memory emptyProof;
        emptyProof.proof = new bytes32[](0);
        emptyProof.flags = new bool[](0);

        uint256 s = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, emptyProof);

        assert(s == tokenIds.length * 1e18);
    }
}

