contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(bytes32 newRoot) public {
        // Fresh pool: this contract does not own the pool NFT (factory minted it to itself),
        // so the onlyOwner modifier must make every setMerkleRoot call revert.
        bool reverted;
        try c.setMerkleRoot(newRoot) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.merkleRoot() != newRoot);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties,
        uint256 inputAmount
    ) public {
        require(_feeRate <= 5_000);
        require(_virtualNftReserves > 0);
        require(inputAmount > 0 && inputAmount < 2**120);

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        uint256 vbr = c.virtualBaseTokenReserves();
        uint256 vnr = c.virtualNftReserves();

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);

        uint256 outputAmount = inputAmount * vbr / (vnr + inputAmount);

        assert(netOutputAmount + feeAmount + protocolFeeAmount == outputAmount && netOutputAmount >= outputAmount / 2);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        require(feeRate <= 5000 || feeRate > 5000); // trivially true precondition, params free
        bool reverted;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool ok;
        if (feeRate > 5000) {
            ok = reverted
                && c.initialized() == false
                && c.virtualBaseTokenReserves() == 0
                && c.virtualNftReserves() == 0
                && c.changeFee() == 0
                && c.feeRate() == 0
                && c.merkleRoot() == bytes32(0)
                && c.useStolenNftOracle() == false
                && c.payRoyalties() == false
                && c.baseToken() == address(0)
                && c.nft() == address(0);
        } else {
            ok = !reverted
                && c.initialized() == true
                && c.baseToken() == baseToken
                && c.nft() == nft
                && c.virtualBaseTokenReserves() == virtualBaseTokenReserves
                && c.virtualNftReserves() == virtualNftReserves
                && c.changeFee() == changeFee
                && c.feeRate() == feeRate
                && c.merkleRoot() == merkleRoot
                && c.useStolenNftOracle() == useStolenNftOracle
                && c.payRoyalties() == payRoyalties;
        }
        assert(ok);
    }
    receive() external payable {}
}

