contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint128 vbr, uint128 vnr, uint16 f, uint256 amount) public {
        require(f <= 5000, "f too big");
        require(vnr >= 2 && amount >= 1 && amount <= vnr / 2, "bounds");
        require(uint256(vbr) <= 1e6 && uint256(vnr) <= 1e6, "small reserves");
        c.initialize(address(0), address(0), vbr, vnr, 0, f, bytes32(0), false, false);
        uint256 denom = uint256(vnr) - amount;
        uint256 input = ((uint256(amount) * uint256(vbr)) + denom - 1) / denom;
        uint256 expFee = input * uint256(f) / 10000;
        (uint256 netInput, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(amount);
        assert(c.feeRate() == f && feeAmount == expFee && netInput == input + expFee + protocolFeeAmount);
    }
    receive() external payable {}
}
